import puppeteer from "puppeteer-extra";
import StealthPlugin from "puppeteer-extra-plugin-stealth"
import { createWriteStream, readFileSync } from "fs"
import { promisify } from "util";

import { sportNameMap } from "../sportNameMap.js";
import { marketNameMap } from "../marketNameMap.js";
import { stripTeamName } from "../util/stripTeamName.js";

// generated by chatGPT https://chatgpt.com/c/a9300588-42f8-40ee-bff4-b00c945cee1e
function convDatetimeToISO(dateStr){

  const parseDateStr = (dateStr) => {
    const [day, month, time] = dateStr.match(/(\d+)\s+(\w+)\s+(\d{2}:\d{2})/).slice(1);
    const [hours, minutes] = time.split(':');
  
    const currentYear = new Date().getFullYear();
    const monthIndex = new Date(`${month} 1, ${currentYear}`).getMonth(); // Get the month index
  
    const date = new Date(currentYear, monthIndex, day, hours, minutes, 0, 0);
    return date;
  };
  
  const date = parseDateStr(dateStr);
  
  // Format the date as ISO 8601
  return date.toISOString();
}

export async function scrapeMatchURL(data, url){

  const bookAbbrev = 'ms';
  // open a file for logging
  const logFilePath = `books/${bookAbbrev}/log.txt`
  const log = createWriteStream(logFilePath, {flags: 'a'});

  // load the book-specific mappings from json files
  const sportNameMappingPath = `books/${bookAbbrev}/sportNameMapping.json`;
  let sportNameMapping;
  try{
    sportNameMapping = Object.freeze(JSON.parse(readFileSync(sportNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${sportNameMappingPath}\n`);
  }
  const marketNameMappingPath = `books/${bookAbbrev}/marketNameMapping.json`;
  let marketNameMapping;
  try{
    marketNameMapping = Object.freeze(JSON.parse(readFileSync(marketNameMappingPath)));
  } catch (error){
    log.write(`Failure! Cannot open file ${marketNameMappingPath}\n`);
  }

  let browser;
  try{
//console.log('data: ');
//console.log(JSON.stringify(data, null, 2));
// https://www.geeksforgeeks.org/how-to-use-goto-in-javascript/
    let page;
    let selector, el, mapping;

    puppeteer.use(StealthPlugin());
    browser = await puppeteer.launch({
        headless: true,
        args: [
            '--no-sandbox',
            '--disable-setuid-sandbox',
            '--disable-dev-shm-usage',
            '--disable-accelerated-2d-canvas',
            '--disable-gpu',
            '--disable-web-security',
        ],
        userDataDir: 'C:\\Users\\User\\AppData\\Local\\Temp\\puppeteer_temp',
    }); 
    page = await browser.newPage();
    await page.setViewport({width:1920, height:768})
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36');
    await page.setExtraHTTPHeaders({
        'Accept-Language': 'en-US,en;q=0.9'
    });
    await page.goto(url);

    try{
      selector = 'iframe[name="sportsbook_iframe"]';
      await page.waitForSelector(selector, {timeout:3000});
      log.write(`Changing context to iframe ${url}\n`)
      const iframeHandle = await page.$(selector);
      page = await iframeHandle.contentFrame();
    } catch{
      log.write(`No iframe ${url}\n`)
    }
  
    // get sport
    selector = 'div.match-title';
    el = await page.waitForSelector(selector);

    const breadcrumbs = await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020').split(' keyboard_arrow_right'), el);
    let sportName = breadcrumbs[0];
    mapping = sportNameMapping.find( m => m.specificName === sportName);
    if(mapping){
      sportName = sportNameMap[mapping.globalID];
    } else{
      log.write(`Failure! sportName Mapping of '${sportName}' does not exist in ${sportNameMappingPath}\n`);
    }
//console.log('>>>>>>>>>>>>>>> scraped sportName: ' + sportName);
    let sport = data.sports.findLast(s => s.name === sportName);
    if(!sport){
      /* sport is new */
      data.sports.push({ name: sportName, matches: [] });
      sport = data.sports.findLast(s => s.name === sportName);
    }
//console.log('sport: ');
//console.log(JSON.stringify(sport, null, 2));

    // get tournament
    // let tournamentName = breadcrumbs[2].trim();
    // mapping = tournamentNameMapping.find( m => m.specificName === tournamentName);
    // if(mapping){
    //   tournamentName = tournamentNameMap[mapping.globalID];
    // } else{
    //   log.write(`Failure! tournamentName Mapping of '${tournamentName}' does not exist in ${tournamentNameMappingPath}\n`);
    // }
//console.log('>>>>>>>>>>>>>>> scraped tournamentname: ' + tournamentName);
    // let tournament = sport.tournaments.findLast(t => t.name === tournamentName );
    // if(!tournament){
    //   /* tournament is new */
    //   sport.tournaments.push({ name: tournamentName, matches: [] });
    //   tournament = sport.tournaments.findLast(t => t.name === tournamentName);
    // }
//console.log('tournament: ');
//console.log(JSON.stringify(tournament, null, 2));

    // get teamHome, teamAway, datetime, mode
    const teams = breadcrumbs[3].split(' - ');
    const teamHome = stripTeamName(teams[0].trim());
    const teamAway = stripTeamName(teams[1].replace(/\s+Hide All/, '').trim());
//console.log('>>>>>>>>>>>>>>> scraped teamHome: ' + teamHome);
//console.log('>>>>>>>>>>>>>>> scraped teamAway: ' + teamAway);
    selector = 'div.match-info > p:nth-child(3)';
    el = await page.waitForSelector(selector);
    const datetime = convDatetimeToISO(await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020').split(', ')[1].trim(), el));
//console.log('>>>>>>>>>>>>>>> scraped datetime: ' + datetime);
//     selector = "div.match-header__bo";
//     el = await page.waitForSelector(selector);
//     const mode = await page.evaluate( e => e.textContent.trim().replace(/\u00a0/g, '\u0020'), el);
//// console.log('>>>>>>>>>>>>>>> scraped mode: ' + mode);
    mapping = sportNameMapping.find( m => m.specificName === sportName);
    let match = sport.matches.findLast(m =>
        m.teamHome === teamHome &&
        m.teamAway === teamAway &&
        m.datetime === datetime
    )
    if(!match){
      log.write(`This match could not yet find a match in data_out.json: ${teamHome}, ${teamAway}, ${datetime}`);
      /* match is new */
      sport.matches.push({ 
        teamHome: teamHome,
        teamAway: teamAway,
        datetime: datetime,
        urls: [],
        markets: []
      });
      match = sport.matches.findLast(m =>
          m.teamHome === teamHome &&
          m.teamAway === teamAway &&
          m.datetime === datetime
      );
    }
    match.urls.push({book: 'Mystake', url: url});
//console.log('match: ');
//console.log(JSON.stringify(match, null, 2));

    // GET ALL THE MARKETS > ODDS > COEFS FOR THIS MATCH
    let market, odd, coef;
    selector = 'div.m-col > div';
    const marketHandles = await page.$$(selector);
    if(marketHandles.length === 0){
      log.write(`No market handles ${url}\n`)
    }
//    console.log(`$$${selector} length: ${marketHandles.length}`);
    for(const marketHandle of marketHandles){

      selector = 'div.title > span';
      let marketName = await marketHandle.$eval(selector, e => e.textContent);
      mapping = marketNameMapping.find( m => m.specificName === marketName);
      if(mapping){
        marketName = marketNameMap[mapping.globalID];
      } else{
        log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
      }
//console.log('>>>>>>>>>>>>>>> scraped marketName: ' + marketName);
      market = match.markets.findLast(m => m.name === marketName);
      if(!market){
        match.markets.push({name: marketName, odds: []});
        market = match.markets.findLast(m => m.name === marketName);
      }
//console.log('market: ');
//console.log(JSON.stringify(market, null, 2));

      selector = 'div.market-odds > div';
      const oddsHandles = await marketHandle.$$(selector);
//      console.log(`$$${selector} length: ${oddsHandles.length}`);
      for(const oddHandle of oddsHandles){
        let oddName = await oddHandle.$eval('p.odd-name', e => e.textContent); 
        oddName = stripTeamName(oddName).replace(/[()+]/g, '');
        if(! marketName.includes('Correct Score') && ! marketName.includes('Total')){
          oddName = oddName
            .replace(/1|2/, (match) => { return match === '1' ? teamHome : teamAway });
        }
//console.log('>>>>>>>>>>>>>>> scraped oddName: ' + oddName);
        odd = market.odds.findLast(o => o.name === oddName);
        if(!odd){
          market.odds.push({name: oddName, coefs: []})
          odd = market.odds.findLast(o => o.name === oddName);
        }
        const value = await oddHandle.$eval('span.coef', e => parseFloat(e.textContent));
//console.log('>>>>>>>>>>>>>>> scraped value: ' + value);
        coef = odd.coefs.findLast(c => c.book === 'Mystake');
        if(!coef){
          odd.coefs.push({book: 'Mystake', value: value});
        }
//console.log('market: ');
//console.log(JSON.stringify(market, null, 2));
      }
    }

  log.write(`Success! scraping a match from ${url}\n`);
  return 0;    

  } catch (error){
    log.write(`Critical Failure! scraping a match from ${url}\n`);
    return -1;
  } finally{
    await browser.close();
    await promisify(log.end).bind(log);
  }
  
}